class ScoutApiException(Exception):
    """Base exception of Scout API exceptions"""


class ApiKeyMissingException(ScoutApiException):
    """Raised when keyword requiring api_key is used but api_key was not provided during library setup"""


class UnsupportedEnvironmentException(ScoutApiException):
    """UnsupportedEnvironmentException is raised when 'environment' is incorrect"""


class InvalidPMIntervalException(ScoutApiException):
    """Raised when time interval parameter is out of range"""


class InvalidStartTimeException(ScoutApiException):
    """Raised when start_time > end_time in time range validation"""


class ConnectionException(ScoutApiException):
    """Generic connection exception"""


class GetRequestException(ScoutApiException):
    """Raised when GET request was unsuccessful"""


class PostRequestException(ScoutApiException):
    """Raised when POST request was unsuccessful"""


class PatchRequestException(ScoutApiException):
    """Raised when PATCH request was unsuccessful"""


class SCFFetchingFailedException(ScoutApiException):
    """Raised when SCF fetching didn't succeeded in given time"""


class TimeRangeException(ScoutApiException):
    """Raised when time range exceds 48h limit"""


class TimeoutException(ConnectionException):
    """Raised when function time out"""


class EmptySCFIDException(ScoutApiException):
    """Raised when SCF id is empty"""
